-- Creates the C++ device for each sample rate. Generated by `rebench new`.

format_version = "1.0"

rtc_bindings = {
  { source = "/environment/system_sample_rate", dest = "/global_rtc/on_sample_rate_changed" },
}

global_rtc = {
  on_sample_rate_changed = function(source_property_path, new_value)
    local sample_rate = jbox.load_property("/environment/system_sample_rate")
    local new_instance = jbox.make_native_object_rw("Instance", { sample_rate })
    jbox.store_property("/custom_properties/instance", new_instance)
  end,
}

rt_input_setup = {
  notify = {
    "/transport/request_reset_audio",
  },
}

sample_rate_setup = {
  native = {
    22050,
    44100,
    48000,
    88200,
    96000,
    192000,
  },
}
